<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import Button from '@/Components/UI/Button.vue'; import PageHeader from '@/Components/UI/PageHeader.vue'; import { Head, Link, router } from '@inertiajs/vue3'; import { reactive } from 'vue';
const props=defineProps<{events:any[];filters:any;types:string[];statuses:string[];customers:any[];isAdmin:boolean;isSupport:boolean}>(); const filters=reactive({...props.filters}); const apply=()=>router.get(route('events.index'),filters,{preserveState:true,replace:true}); const reset=()=>{filters.search='';filters.event_type='';filters.status='';filters.customer_id='';apply()};
</script>
<template><Head title="Events"/><AuthenticatedLayout><template #header><PageHeader title="Events"><template #actions><Link v-if="isAdmin" :href="route('admin.customers.index')" class="fe-btn fe-btn-primary">Create Client</Link></template></PageHeader></template><div class="fe-page fe-page-wide"><form @submit.prevent="apply" class="fe-card fe-card-muted flex flex-wrap gap-2 p-3"><input v-model="filters.search" placeholder="Search events" class="w-full min-w-0 sm:w-auto sm:min-w-52"><select v-model="filters.event_type" class="w-full min-w-0 sm:w-auto"><option value="">All types</option><option v-for="type in types" :value="type">{{type}}</option></select><select v-if="isAdmin" v-model="filters.status" class="w-full min-w-0 sm:w-auto"><option value="">All statuses</option><option v-for="item in statuses" :value="item">{{item}}</option></select><select v-if="isAdmin" v-model="filters.customer_id" class="w-full min-w-0 sm:w-auto"><option value="">All clients</option><option v-for="customer in customers" :value="customer.id">{{customer.name}}</option></select><Button type="submit">Search</Button><Button type="button" variant="ghost" @click="reset">Reset</Button></form><div class="mt-4 fe-card overflow-hidden"><Link v-for="event in events" :key="event.id" :href="route('events.show', event.id)" class="block border-b border-[color:var(--fe-border)] p-4 hover:bg-[color:var(--fe-surface-elevated)]"><b class="break-words">{{event.title || 'Invitation setup not completed'}}</b><span class="mt-1 block break-words text-sm text-[color:var(--fe-text-secondary)]">{{event.customer?.name}} · {{isAdmin || isSupport ? event.status : event.invitation_status.replaceAll('_', ' ')}}<span v-if="event.live_version"> · Version {{event.live_version}}</span></span></Link><p v-if="!events.length" class="p-4 text-[color:var(--fe-text-secondary)]">No events match your search or filters.</p></div></div></AuthenticatedLayout></template>
